/* i18n dictionary for the trading journal.
 *
 * Every user-facing string lives here, keyed by language code. The base
 * language is Indonesian (the app's original UI copy); any key missing in a
 * language falls back to it. Language names are written in their OWN language
 * so the selector reads natively. `rtl: true` flips <html dir> when selected.
 *
 * CSV export/import stays Indonesian on purpose (headers, ya/tidak,
 * disiplin/melanggar): it is a data format whose roundtrip depends on stable
 * header names, not UI copy. See IMPORT_SYNONYMS in index.html.
 */
